      @{ title = "⚠️ ارتفاع حرارة محرك V8 AMG في ازدحام دبي الصيفي"; body = "محرك الـ4.0 لتر المزدوج التوربو المشتق من AMG في DB11 وVantage وDBS وDBX يُولّد حرارة هائلة حتى عند أحمال متوسطة. في ازدحام دبي الصيفي تعمل دائرة التبريد عند حدودها القصوى. توصي فيكس هايف باستبدال سائل التبريد كل سنتين واختبار الثيرموستات عند كل صيانة رئيسية." },
