    arSpecialty = "Continental GT · Flying Spur · Bentayga · Mulsanne"
    arIntro = @(
      "تمثل بنتلي قمة الحرفية البريطانية في صناعة السيارات — كل سيارة تُجمَّع يدوياً في كرو بإنجلترا باهتمام بالتفاصيل يستغرق أسابيع لكل مركبة على حدة. في دبي، تُعدّ بنتلي من أكثر ماركات الفخامة حضوراً على الطرق، لا سيما سيارة Bentayga التي تحظى بشعبية كبيرة في الإمارات.",
      "تشترك موديلات بنتلي الحالية مع منصات فولكسفاغن العليا. تستخدم Continental GT وFlying Spur منصة MSB بمحرك W12 أو V8 مزدوج التوربو، فيما تقوم Bentayga على منصة MLB Evo المشتركة مع Audi Q7 وPorsche Cayenne. هذه المنصات متطورة للغاية وتتطلب معدات تشخيص تفوق قدرات OBD-II القياسية بكثير.",
      "في مناخ دبي تواجه أنظمة التعليق الهوائي لبنتلي تحديات بالغة. التقلبات الحرارية المتكررة تُسبب تصلب وتشقق أكياس الهواء المطاطية مما يؤدي إلى تسريب بطيء يظهر في صورة انخفاض طفيف في ارتفاع إحدى زوايا الهيكل صباحاً. نفحص حالة التعليق الهوائي عند كل صيانة رئيسية.",
      "في فيكس هايف نتعامل مع كل سيارة بنتلي بالاحترام الذي تستحقه. نتبع إجراءات صيانة مجموعة فولكسفاغن للمنصات الأساسية ونستخدم سوائل معتمدة من بنتلي وقطعاً معادلة OEM مع الحفاظ بسجلات صيانة كاملة وقابلة للتحقق."
    )
    arIssues = @(
      @{ title = "⚠️ تزليق محرك W12 وتآكل سلسلة التوقيت"; body = "محرك W12 الـ6.0 لتر ذو الاثني عشر أسطوانة يتطلب تزليقاً دقيقاً. في دبي، تتدهور جودة الزيت بسرعة بسبب الحرارة الشديدة وأحمال ضاغط التكييف. نوصي بتغيير الزيت كل 10,000 كم بزيت تخليقي 0W-40 معتمد من بنتلي لتفادي امتداد سلسلة التوقيت." },
      @{ title = "⚠️ تدهور منظومة التعليق الهوائي في حرارة الإمارات"; body = "أنظمة التعليق الهوائي في Bentayga وFlying Spur وContinental GT حساسة للتقلبات الحرارية. يتسبب التدوير الحراري المتكرر بين البيئة الداخلية المكيفة والحرارة الخارجية في تصلب وتشقق أكياس الهواء المطاطية. نفحص ضغط الهواء وحالة الأكياس عند كل صيانة." },
      @{ title = "⚠️ صيانة التشطيبات الداخلية والخارجية الفاخرة في دبي"; body = "يتطلب الجلد المخيط يدوياً والخشب المصقول والزجاج والألومنيوم المصقول رعاية متخصصة. الأشعة فوق البنفسجية الشديدة والغبار في دبي تُلحق ضرراً بالغاً بدون منتجات العناية المعتمدة. فريق التلميع في فيكس هايف يحمل المنتجات الصحيحة لكل سطح من أسطح بنتلي." },
      @{ title = "⚠️ تردد ناقل DCT في ازدحام المدينة"; body = "ناقل الحركة ذو القابضين المزدوجين في Continental GT وFlying Spur مُعايَر للتسارع السريع على السرعات المتوسطة والعالية. في ازدحام دبي يُقضي وقتاً طويلاً في منطقة الانزلاق المنخفض مما يُسبب تدهوراً في سائل ناقل الحركة وتذبذباً ملحوظاً. نوصي بتغيير سائل DCT كل 40,000 كم." }
    )
    arFaqs = @(
      @{ q = "كم تكلفة صيانة بنتلي في دبي؟"; a = "تبدأ الصيانة الخفيفة من 1200 إلى 2000 درهم حسب الموديل والمحرك. الصيانة الشاملة تتراوح بين 4000 و8000 درهم وتشمل سائل ناقل الحركة وسائل التبريد وشمعات الإشعال." },
      @{ q = "كم مرة يجب تغيير زيت محرك W12 في دبي؟"; a = "نوصي بتغيير الزيت كل 10,000 كم في الإمارات بدلاً من الفاصل الأوروبي 15,000 كم. حرارة دبي الشديدة تُسرّع تدهور الزيت التخليقي مما قد يُلحق ضرراً بسلسلة التوقيت." },
      @{ q = "هل تمتلك فيكس هايف أدوات تشخيص لسيارات بنتلي؟"; a = "نعم. تستخدم موديلات بنتلي معمارية إلكترونية من مجموعة فولكسفاغن يدعمها الكامل أدوات التشخيص لدينا، بما في ذلك W12 وV8 وناقل الحركة والتعليق الهوائي." },
      @{ q = "هل من الآمن صيانة بنتلي في ورشة مستقلة بدبي؟"; a = "نعم. تنظيمات حماية المستهلك في الإمارات تتيح ذلك دون المساس بالضمان شريطة استخدام القطع والسوائل الصحيحة. فيكس هايف تُصدر سجل صيانة كاملاً ومفصّلاً لكل زيارة." },
