    arH1 = "إصلاح وصيانة BYD في دبي"
    arHeroSub = "متخصصون في سيارات BYD الكهربائية وهجينة القابس في دبي — Atto 3 وSeal وHan وDolphin. فحص صحة البطارية وتحديثات البرامج."
    arSpecialty = "Atto 3 · Seal · Han · Tang · Dolphin"
    arIntro = @(
      "برزت BYD — اختصار لـ Build Your Dreams — كواحدة من أبرز قوى صناعة السيارات في العقد الثالث من الألفية الثالثة، متجاوزةً تسلا عالمياً من حيث إجمالي مبيعات السيارات الكهربائية وهجينة القابس. في الإمارات، رسّخت BYD حضوراً قوياً ومتنامياً بسرعة، إذ باتت Atto 3 من أكثر السيارات الكهربائية مبيعاً في البلاد.",
      "تتميز BYD بأنها تُصنّع خلايا البطاريات والمحركات الكهربائية والإلكترونيات والبرامج بنفسها — مستوى من التكامل الرأسي يمنحها تحكماً استثنائياً في منتجها. تقنية Blade Battery المستخدمة في Atto 3 وSeal وHan تعتمد على كيمياء فوسفات الحديد الليثيومي في تصميم cell-to-pack الذي يلغي الوحدات التقليدية.",
      "في مناخ دبي، تواجه سيارات BYD الكهربائية تحديات خاصة بإدارة الحرارة. يتطلب حزمة البطارية الحفاظ على نطاق حرارة دقيق لتسريع الشحن الأمثل والمدى والعمر الافتراضي. كما أن خسارة الكفاءة جراء تشغيل مكيف الهواء في حرارة دبي قد تُخفض المدى الفعلي بنسبة 25-35% مقارنة بالأرقام الأوروبية.",
      "تتلقى سيارات BYD أيضاً تحديثات برامج OTA يمكن أن تُعدّل منحنيات الشحن وسلوك الفرملة الاسترجاعية وميزات مساعدة السائق. في فيكس هايف يواكب فريقنا إصدارات برامج BYD ونمتلك قدرات تشخيصية لمعمارية DiLink والأنظمة الأساسية."
    )
    arIssues = @(
      @{ title = "⚠️ تراجع مدى البطارية وإدارة الحرارة في حر دبي"; body = "بطارية BYD Blade من نوع LFP معروفة بثباتها الحراري واستقرارها، لكن الحرارة المرتفعة تُسرّع تدهور الطاقة إذا لم تعمل دائرة التبريد بكفاءة. نوصي بفحص سنوي لصحة البطارية يشمل قياس السعة المتاحة وفحص دائرة التبريد والتحقق من إصدار برنامج BMS." },
      @{ title = "⚠️ مشاكل شحن مع محطات الجهة الثالثة في الإمارات"; body = "تستخدم سيارات BYD في الإمارات معيار CCS2 للشحن السريع. تنشأ مشاكل التوافق مع بعض محطات الشحن القديمة في الدولة وتظهر في صورة فشل في بدء الجلسة أو انقطاع مبكر. في الغالب تعكس هذه المشاكل عدم تطابق إصدارات البرامج وليست أعطالاً في الأجهزة." },
      @{ title = "⚠️ تجمد نظام DiLink وأعطال الاتصال"; body = "أنظمة DiLink 4.0 قد تعاني من تجمد الشاشة وبطء الاستجابة ومشاكل البلوتوث في الإصدارات القديمة. كثير من هذه المشاكل تم حلها في تحديثات OTA اللاحقة. نحمل في فيكس هايف أحدث ملفات تحديث BYD ونُجري التحديثات السلكية للسيارات التي تواجه صعوبة في التحديث التلقائي." },
      @{ title = "⚠️ تقليل طاقة المحرك الكهربائي بسبب الحرارة في السرعات العالية"; body = "تُشعّ محركات BYD الكهربائية حرارة تُقلّص الهامش الحراري المتاح في الأجواء الحارة. قيادة السرعة العالية المطوّلة على الطريق السريع في درجات 45°C قد تُسبب تقليل الطاقة كإجراء وقائي. إذا ظهر هذا التقليل في ظروف عادية، فقد يشير إلى انسداد في دائرة تبريد المحرك." }
    )
    arFaqs = @(
      @{ q = "كم تكلفة صيانة BYD في دبي؟"; a = "السيارات الكهربائية BYD تتطلب صيانة روتينية أقل بكثير من المحركات الحرارية. تكلف الصيانة السنوية في فيكس هايف عادةً 400 إلى 700 درهم وتشمل سائل الفرامل وفلتر الهواء والمساحات وتدوير الإطارات وفحص صحة البطارية." },
      @{ q = "كم مرة يجب فحص صحة بطارية BYD في دبي؟"; a = "نوصي بفحص سنوي لصحة البطارية يستغرق 45 دقيقة ويشمل تسجيل بيانات BMS وفحص توازن خلايا الجهد وقياس السعة المتاحة وفحص دائرة التبريد والتحقق من إصدار البرنامج." },
      @{ q = "هل تدعم فيكس هايف تحديثات OTA لسيارات BYD؟"; a = "نعم. نواكب جدول إصدارات برامج BYD ونُجري التحديثات السلكية للسيارات التي تواجه مشكلة في التحديث التلقائي، كما نتحقق من صحة تطبيق التحديثات." },
      @{ q = "لماذا مدى Atto 3 أقل من المعدل المُعلَن في دبي؟"; a = "انخفاض المدى بنسبة 25-35% عن قيمة WLTP أمر طبيعي تماماً في دبي، السبب الرئيسي هو حمل مكيف الهواء الذي يستهلك 2-4 كيلوواط باستمرار. إذا انخفض المدى بشكل ملحوظ مقارنةً بتجربتك السابقة الشخصية، يُوصى بفحص البطارية." },
